<?php
session_start(); require '../database/config.php'; require '../includes/auth.php'; requireAdmin();
$pdo=getConnection();
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT); $status=$_POST['account_status']??''; if($id && in_array($status,['active','inactive','suspended'],true)){ $s=$pdo->prepare('UPDATE users SET account_status=:status WHERE id=:id AND role<>\'admin\''); $s->execute(['status'=>$status,'id'=>$id]); } header('Location: users.php?message='.urlencode('Account status updated.')); exit; }
$rows=$pdo->query("SELECT id,username,email,first_name,last_name,phone,role,account_status,created_at FROM users ORDER BY created_at DESC")->fetchAll(); $message=$_GET['message']??null;
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Users | Admin</title><link rel="stylesheet" href="../assets/css/admin.css"></head><body><header class="admin-header"><a href="../index.php" class="brand-link"><img src="../assets/images/logo-dark.svg" alt="Obeda Dormitories"></a><div><span>Administrator</span><a class="logout" href="../logout.php">Logout</a></div></header><div class="admin-layout"><aside><div class="side-title">ADMIN</div><nav><a href="dashboard.php">Dashboard</a><a href="viewing_requests.php">Viewing Requests</a><a href="room_applications.php">Room Applications</a><a href="rooms.php">Rooms</a><a href="dormitories.php">Dormitories</a><a class="active" href="users.php">Users</a></nav></aside><main class="admin-main"><h1>Users</h1><?php if($message): ?><div class="alert success"><?=h($message)?></div><?php endif; ?><div class="panel table-wrap"><table><thead><tr><th>User</th><th>Contact</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=h($r['first_name'].' '.$r['last_name'])?><br><small>@<?=h($r['username'])?></small></td><td><?=h($r['email'])?><br><small><?=h($r['phone'] ?: 'No phone')?></small></td><td><?=h($r['role'])?></td><td><span class="status <?=h($r['account_status'])?>"><?=h(ucfirst($r['account_status']))?></span></td><td><?php if($r['role']==='admin'): ?>Protected<?php else: ?><form method="post" class="inline-actions"><input type="hidden" name="id" value="<?=h((string)$r['id'])?>"><select name="account_status"><option value="active">Active</option><option value="inactive">Inactive</option><option value="suspended">Suspended</option></select><button>Save</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></main></div></body></html>
